window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bcceddfca54a3b61"]={"versions": [{"id": "FIG-bcceddfca54a3b61", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Datenlayout- und Serialisierungsdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (ara::com / SOME/IP-Serialisierung). Das Schaubild visualisiert die byteweise Repräsentation und Längenfeldschachtelung eines mehrdimensionalen Vektors bzw. dynamischen Arrays (SOME/IP Array Serialization).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordnetes Längenfeld: <code>Length n</code> mit einer konfigurierbaren Bitbreite von 8, 16 oder 32 Bit, das die Gesamtlänge des äußeren Vektors in Bytes (<code>n [byte]</code>) beschreibt.\n</li><li>Äußere Vektorelemente: Sub-Vektoren bzw. innere Arrays <code>Element_a[1][j...k_1]</code>, <code>Element_a[2][j...k_2]</code> usw.\n</li><li>Lokale Längenfelder innerer Dimensionen: <code>L_1</code> und <code>L_2</code>, die jeweils die Länge der Nutzdaten des spezifischen inneren Vektors in Bytes angeben (<code>L_1 [byte]</code>, <code>L_2 [byte]</code>).\n</li><li>Nutzdaten-Elemente innerer Vektoren: Sequenzen einzelner Datenelemente <code>E1,1</code>, <code>E1,2</code> bis <code>E1,k_1</code> (für Element 1) sowie <code>E1,1</code>, <code>E1,2</code> bis <code>E1,k_2</code> (für Element 2), gefolgt von weiteren Vektorelementen (<code>...</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell im Stream:</p>\n<ol class=\"fig-list\"><li>Voranstellen des Hauptlängenfeldes <code>Length n</code> (Größe: 8, 16 oder 32 Bit).\n</li><li>Für die erste Dimension bzw. das erste Unterelement (<code>Element_a[1]</code>): Voranstellen des inneren Längenfeldes <code>L_1</code>, gefolgt von den sequenziell serialisierten Elementen <code>E1,1</code> bis <code>E1,k_1</code>. Der Gültigkeitsbereich des inneren Längenfeldes <code>L_1 [byte]</code> deckt exakt diese Elemente ab (ohne das Feld <code>L_1</code> selbst).\n</li><li>Für das nachfolgende Unterelement (<code>Element_a[2]</code>): Voranstellen des inneren Längenfeldes <code>L_2</code>, gefolgt von den Nutzdaten-Elementen <code>E1,1</code> bis <code>E1,k_2</code> mit Länge <code>L_2 [byte]</code>.\n</li><li>Das Gesamtlängenfeld <code>n [byte]</code> umfasst die Summe aller inneren Längenfelder und Nutzdatenelemente des gesamten mehrdimensionalen Vektors, schließt jedoch das eigene Längenfeld <code>Length n</code> aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bei mehrdimensionalen Vektoren muss jede Dimension bzw. jedes Sub-Array über ein eigenes, vorangestelltes Längenfeld verfügen.\n</li><li>Längenangaben beziehen sich jeweils auf die Nutzlast des betreffenden Vektors/Arrays exklusive des eigenen Längenfeldes.\n</li><li>Das äußere Längenfeld deckt alle untergeordneten Vektoren inklusive deren Längenfelder ab.\n</li><li>Die Bitbreite des Längenfeldes (8, 16 oder 32 Bit) richtet sich nach der Konfiguration der Transformations-Properties (z. B. <code>sizeOfArrayLengthField</code> in den SOME/IP-Transformationsprofilen).\n</li></ul>"}, {"id": "FIG-b1dba1938cc09e5f", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Datenlayout- und Serialisierungsdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (ara::com / SOME/IP-Serialisierung). Das Schaubild visualisiert die byteweise Repräsentation und Längenfeldschachtelung eines mehrdimensionalen Vektors bzw. dynamischen Arrays (SOME/IP Array Serialization).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Übergeordnetes Längenfeld: <code>Length n</code> mit einer konfigurierbaren Bitbreite von 8, 16 oder 32 Bit, das die Gesamtlänge des äußeren Vektors in Bytes (<code>n [byte]</code>) beschreibt.\n</li><li>Äußere Vektorelemente: Sub-Vektoren bzw. innere Arrays <code>Element_a[1][j...k_1]</code>, <code>Element_a[2][j...k_2]</code> usw.\n</li><li>Lokale Längenfelder innerer Dimensionen: <code>L_1</code> und <code>L_2</code>, die jeweils die Länge der Nutzdaten des spezifischen inneren Vektors in Bytes angeben (<code>L_1 [byte]</code>, <code>L_2 [byte]</code>).\n</li><li>Nutzdaten-Elemente innerer Vektoren: Sequenzen einzelner Datenelemente <code>E1,1</code>, <code>E1,2</code> bis <code>E1,k_1</code> (für Element 1) sowie <code>E1,1</code>, <code>E1,2</code> bis <code>E1,k_2</code> (für Element 2), gefolgt von weiteren Vektorelementen (<code>...</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell im Stream:</p>\n<ol class=\"fig-list\"><li>Voranstellen des Hauptlängenfeldes <code>Length n</code> (Größe: 8, 16 oder 32 Bit).\n</li><li>Für die erste Dimension bzw. das erste Unterelement (<code>Element_a[1]</code>): Voranstellen des inneren Längenfeldes <code>L_1</code>, gefolgt von den sequenziell serialisierten Elementen <code>E1,1</code> bis <code>E1,k_1</code>. Der Gültigkeitsbereich des inneren Längenfeldes <code>L_1 [byte]</code> deckt exakt diese Elemente ab (ohne das Feld <code>L_1</code> selbst).\n</li><li>Für das nachfolgende Unterelement (<code>Element_a[2]</code>): Voranstellen des inneren Längenfeldes <code>L_2</code>, gefolgt von den Nutzdaten-Elementen <code>E1,1</code> bis <code>E1,k_2</code> mit Länge <code>L_2 [byte]</code>.\n</li><li>Das Gesamtlängenfeld <code>n [byte]</code> umfasst die Summe aller inneren Längenfelder und Nutzdatenelemente des gesamten mehrdimensionalen Vektors, schließt jedoch das eigene Längenfeld <code>Length n</code> aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bei mehrdimensionalen Vektoren muss jede Dimension bzw. jedes Sub-Array über ein eigenes, vorangestelltes Längenfeld verfügen.\n</li><li>Längenangaben beziehen sich jeweils auf die Nutzlast des betreffenden Vektors/Arrays exklusive des eigenen Längenfeldes.\n</li><li>Das äußere Längenfeld deckt alle untergeordneten Vektoren inklusive deren Längenfelder ab.\n</li><li>Die Bitbreite des Längenfeldes (8, 16 oder 32 Bit) richtet sich nach der Konfiguration der Transformations-Properties (z. B. <code>sizeOfArrayLengthField</code> in den SOME/IP-Transformationsprofilen).\n</li></ul>"}], "trans": [{"from": "FIG-bcceddfca54a3b61", "to": "FIG-b1dba1938cc09e5f", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
